/// Whether the path belongs to the libm crate, rather than a user namespace.
pub fn is_libm_path(name: &str) -> bool {
    name.split("::").next() == Some("libm")
}

/// Exact std shims intercepted before the collector's forbidden-std guard.
pub fn is_intrinsic_lowered_cmath_shim(name: &str) -> bool {
    matches!(
        name,
        "std::sys::cmath::acos"
            | "std::sys::cmath::acosf"
            | "std::sys::cmath::acosh"
            | "std::sys::cmath::acoshf"
            | "std::sys::cmath::asin"
            | "std::sys::cmath::asinf"
            | "std::sys::cmath::asinh"
            | "std::sys::cmath::asinhf"
            | "std::sys::cmath::atan"
            | "std::sys::cmath::atan2"
            | "std::sys::cmath::atan2f"
            | "std::sys::cmath::atanf"
            | "std::sys::cmath::atanh"
            | "std::sys::cmath::atanhf"
            | "std::sys::cmath::cbrt"
            | "std::sys::cmath::cbrtf"
            | "std::sys::cmath::cos"
            | "std::sys::cmath::cosf"
            | "std::sys::cmath::cosh"
            | "std::sys::cmath::coshf"
            | "std::sys::cmath::expm1"
            | "std::sys::cmath::expm1f"
            | "std::sys::cmath::hypot"
            | "std::sys::cmath::hypotf"
            | "std::sys::cmath::log1p"
            | "std::sys::cmath::log1pf"
            | "std::sys::cmath::sin"
            | "std::sys::cmath::sinf"
            | "std::sys::cmath::sinh"
            | "std::sys::cmath::sinhf"
            | "std::sys::cmath::tan"
            | "std::sys::cmath::tanf"
            | "std::sys::cmath::tanh"
            | "std::sys::cmath::tanhf"
            | "std::sys::cmath::tgamma"
            | "std::sys::cmath::tgammaf"
    )
}

/// Sincos retains its importer tuple expansion into two scalar placeholders.
pub fn libm_sincos_lowering(name: &str) -> Option<RustFloatMathLowering> {
    if !is_libm_path(name) {
        return None;
    }
    match name.rsplit("::").next().unwrap_or(name) {
        "sincos" => Some(RustFloatMathLowering::Sincos { is_f64: true }),
        "sincosf" => Some(RustFloatMathLowering::Sincos { is_f64: false }),
        _ => None,
    }
}

/// Return whether `name` is the `f64` (`Some(true)`) or `f32` (`Some(false)`) `libm::sincos` entry.
pub fn libm_sincos_is_f64(name: &str) -> Option<bool> {
    match libm_sincos_lowering(name) {
        Some(RustFloatMathLowering::Sincos { is_f64 }) => Some(is_f64),
        _ => None,
    }
}
